}

Method.Source:
[DataMemberAttribute('InvoiceList'),
 SysOperationControlVisibilityAttribute(false),
    AifCollectionTypeAttribute(identifierStr(_invoiceList), Types::Int64)]
public List parmInvoiceList(List _invoiceList = invoiceList)
{
    invoiceList = _invoiceList;
    return invoiceList;
}

[
